public with sharing class ContactDomainService {
    private static final Integer SOQL_IN_LIMIT = 1000;

    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> groupedContacts = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return groupedContacts;
        }

        List<Id> accountIdList = new List<Id>(accountIds);

        for (Integer startIndex = 0; startIndex < accountIdList.size(); startIndex += SOQL_IN_LIMIT) {
            Integer chunkEnd = (startIndex + SOQL_IN_LIMIT < accountIdList.size())
                ? startIndex + SOQL_IN_LIMIT
                : accountIdList.size();

            Set<Id> chunk = new Set<Id>();
            for (Integer i = startIndex; i < chunkEnd; i++) {
                chunk.add(accountIdList[i]);
            }

            List<Contact> contacts = [
                SELECT Id, Email, AccountId
                FROM Contact
                WHERE AccountId IN :chunk
                  AND Email != null
                  AND Email != ''
                WITH USER_MODE
            ];

            for (Contact contact : contacts) {
                String email = contact.Email;

                if (String.isBlank(email) || !email.contains('@')) {
                    continue;
                }

                String domain = email.substring(email.indexOf('@') + 1).toLowerCase();

                if (String.isBlank(domain)) {
                    continue;
                }

                if (!groupedContacts.containsKey(domain)) {
                    groupedContacts.put(domain, new List<Contact>());
                }

                groupedContacts.get(domain).add(contact);
            }
        }

        return groupedContacts;
    }
}
