public with sharing class Opportunities extends fflib_SObjectDomain {

    public Opportunities(List<SObject> sObjectList) {
        super(sObjectList);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }

    public override void onAfterInsert() {
        Set<Id> qualifyingIds = new Set<Id>();

        for (Opportunity opportunity : (List<Opportunity>) getRecords()) {
            if (opportunity.StageName == 'Closed Won') {
                qualifyingIds.add(opportunity.Id);
            }
        }

        startFulfilment(qualifyingIds);
    }

    public override void onAfterUpdate(Map<Id, SObject> oldRecords) {
        Set<Id> qualifyingIds = new Set<Id>();

        for (Opportunity opportunity : (List<Opportunity>) getRecords()) {
            Opportunity oldOpportunity = (Opportunity) oldRecords.get(opportunity.Id);

            if (oldOpportunity.StageName != 'Closed Won' && opportunity.StageName == 'Closed Won') {
                qualifyingIds.add(opportunity.Id);
            }
        }

        startFulfilment(qualifyingIds);
    }

    private void startFulfilment(Set<Id> opportunityIds) {
        if (opportunityIds.isEmpty()) {
            return;
        }

        Application.Service.newInstance(IOpportunityFulfilmentService.class)
            .startFulfilment(opportunityIds);
    }
}
