public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    public AccountsSelector() {
        setDataAccessMode(fflib_QueryFactory.DataAccessMode.USER_MODE);
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };
        Set<Schema.SObjectField> selectedFields = new Set<Schema.SObjectField>(fields);

        Schema.FieldSet creditReviewFieldSet = Schema.SObjectType.Account.fieldSets.getMap().get('Credit_Review');
        if (creditReviewFieldSet != null) {
            for (Schema.FieldSetMember fieldSetMember : creditReviewFieldSet.getFields()) {
                Schema.SObjectField field = fieldSetMember.getSObjectField();
                if (field != null && !selectedFields.contains(field)) {
                    fields.add(field);
                    selectedFields.add(field);
                }
            }
        }
        return fields;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        fflib_QueryFactory queryFactory = newQueryFactory()
            .addSubquery(new ContactsSelector().newQueryFactory());
        queryFactory.addWhereClause('Id IN :accountIds');

        return (List<Account>) Database.query(
            queryFactory.toSOQL(),
            new Map<String, Object>{'accountIds' => accountIds}
        );
    }
}
