public with sharing class CaseSurveyJob implements Queueable {
    private final List<Id> caseIds;

    // Kept for compatibility with the original single-case constructor.
    public CaseSurveyJob(Id caseId) {
        this.caseIds = new List<Id>{ caseId };
    }

    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds;
    }

    public void execute(QueueableContext context) {
        // Re-query so we only create surveys for cases that are still closed
        // and still have a contact.
        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId, IsClosed
            FROM Case
            WHERE Id IN :caseIds
        ];

        for (Case cs : cases) {
            try {
                if (cs.IsClosed && cs.ContactId != null) {
                    Task surveyTask = new Task(
                        WhatId = cs.Id,
                        WhoId = cs.ContactId,
                        Subject = 'CSAT survey: ' + cs.CaseNumber,
                        ActivityDate = Date.today().addDays(2),
                        Status = 'Not Started'
                    );
                    insert surveyTask;
                }
            } catch (Exception e) {
                // Log and continue so one case failure does not stop the batch.
                System.debug('Error creating survey task for case ' + cs.Id + ': ' + e.getMessage());
            }
        }
    }
}
