import { LightningElement, api, wire } from 'lwc';
import { getRecord } from 'lightning/uiRecordApi';

const FIELDS = [
    'Account.Name',
    'Account.Industry',
    'Account.AnnualRevenue',
    'Account.Owner.Name'
];

export default class AccountHeader extends LightningElement {
    _recordId;
    record;
    error;

    @api
    get recordId() {
        return this._recordId;
    }

    set recordId(value) {
        if (value !== this._recordId) {
            this._recordId = value;
            this.record = undefined;
            this.error = undefined;
        }
    }

    @wire(getRecord, { recordId: '$recordId', fields: FIELDS })
    wiredRecord({ data, error }) {
        if (data) {
            this.record = data;
            this.error = undefined;
        } else if (error) {
            this.record = undefined;
            this.error = error;
        }
    }

    get isLoading() {
        return !this.record && !this.error;
    }

    get name() {
        return this.record?.fields?.Name?.value;
    }

    get industry() {
        return this.record?.fields?.Industry?.value;
    }

    get revenue() {
        return this.record?.fields?.AnnualRevenue?.value;
    }

    get ownerName() {
        const ownerField = this.record?.fields?.Owner;
        if (!ownerField) {
            return '';
        }
        if (ownerField.displayValue) {
            return ownerField.displayValue;
        }
        const ownerValue = ownerField.value;
        if (ownerValue && typeof ownerValue === 'object') {
            if (typeof ownerValue.Name === 'string') {
                return ownerValue.Name;
            }
            if (ownerValue.Name && typeof ownerValue.Name === 'object' && ownerValue.Name.value) {
                return ownerValue.Name.value;
            }
        }
        return '';
    }
}
