import { LightningElement, track } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    @track stats;
    @track error;

    sessionToken = 0;
    timer = null;
    requestInFlight = false;
    _isConnected = false;

    connectedCallback() {
        this.sessionToken += 1;
        const token = this.sessionToken;

        this._isConnected = true;
        this.stats = null;
        this.error = undefined;
        this.requestInFlight = false;

        this.clearTimer();
        this.removeVisibilityListener();
        this.addVisibilityListener();

        this.refresh(token);
    }

    disconnectedCallback() {
        this._isConnected = false;
        this.sessionToken += 1;
        this.clearTimer();
        this.removeVisibilityListener();
        this.requestInFlight = false;
    }

    addVisibilityListener() {
        document.addEventListener('visibilitychange', this.handleVisibilityChange);
    }

    removeVisibilityListener() {
        document.removeEventListener('visibilitychange', this.handleVisibilityChange);
    }

    handleVisibilityChange = () => {
        if (document.visibilityState === 'visible') {
            this.refresh(this.sessionToken);
        } else {
            this.clearTimer();
        }
    };

    refresh(token = this.sessionToken) {
        if (!this._isConnected || token !== this.sessionToken) {
            return;
        }

        if (document.visibilityState === 'hidden') {
            this.clearTimer();
            return;
        }

        if (this.requestInFlight) {
            this.scheduleNextRefresh(token);
            return;
        }

        this.requestInFlight = true;

        getQueueStats()
            .then((result) => {
                if (!this._isConnected || token !== this.sessionToken) {
                    return;
                }

                this.stats = result;
                this.error = undefined;
            })
            .catch((error) => {
                if (!this._isConnected || token !== this.sessionToken) {
                    return;
                }

                this.error = error.body && error.body.message
                    ? error.body.message
                    : error.message;
            })
            .finally(() => {
                if (!this._isConnected || token !== this.sessionToken) {
                    return;
                }

                this.requestInFlight = false;
                this.scheduleNextRefresh(token);
            });
    }

    scheduleNextRefresh(token = this.sessionToken) {
        if (!this._isConnected || token !== this.sessionToken) {
            return;
        }

        if (document.visibilityState === 'hidden') {
            this.clearTimer();
            return;
        }

        this.clearTimer();
        this.timer = setTimeout(() => {
            this.timer = null;
            this.refresh(token);
        }, 60000);
    }

    clearTimer() {
        if (this.timer) {
            clearTimeout(this.timer);
            this.timer = null;
        }
    }
}
