public class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Stage one NPSP Data Import record per gift.
        List<npsp__DataImport__c> dataImports = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            dataImports.add(new npsp__DataImport__c(
                npsp__Contact1_Firstname__c = gift.firstName,
                npsp__Contact1_Lastname__c = gift.lastName,
                npsp__Contact1_Personal_Email__c = gift.email,
                npsp__Donation_Amount__c = gift.amount,
                npsp__Donation_Date__c = gift.giftDate,
                npsp__Donation_Donor__c = 'Contact1'
            ));
        }

        // Process synchronously through NPSP's BDI Apex API.
        try {
            npsp.BDI_DataImport_API.processDataImportRecords(dataImports);
        } catch (Exception ex) {
            for (Integer i = 0; i < gifts.size(); i++) {
                ImportResult result = new ImportResult();
                result.success = false;
                result.errorMessage = ex.getMessage();
                results.add(result);
            }
            return results;
        }

        // Build one result per input gift, preserving input order.
        for (Integer i = 0; i < dataImports.size(); i++) {
            ImportResult result = new ImportResult();
            npsp__DataImport__c dataImport = dataImports.get(i);

            result.success = isImported(dataImport);
            result.contactId = dataImport.npsp__Contact1Imported__c;
            result.opportunityId = dataImport.npsp__DonationImported__c;
            result.errorMessage = dataImport.npsp__FailureInformation__c;

            if (!result.success && String.isBlank(result.errorMessage)) {
                result.errorMessage = 'NPSP Data Import failed for this record.';
            }

            results.add(result);
        }

        return results;
    }

    private static Boolean isImported(npsp__DataImport__c dataImport) {
        if (dataImport.npsp__Status__c == 'Imported') {
            return true;
        }
        if (dataImport.npsp__Status__c != null) {
            return false;
        }
        // Defensive fallback if status was not populated but NPSP still populated the lookups.
        return dataImport.npsp__Contact1Imported__c != null
            && dataImport.npsp__DonationImported__c != null;
    }
}
