public class GiftService {
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('Contact does not exist.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date is required.');
        }

        Contact contact = [
            SELECT Id, AccountId, FirstName, LastName
            FROM Contact
            WHERE Id = :contactId
        ];
        if (contact == null) {
            throw new IllegalArgumentException('Contact does not exist.');
        }
        if (contact.AccountId == null) {
            throw new IllegalArgumentException('Contact does not belong to a household account.');
        }

        String firstName = contact.FirstName == null ? '' : contact.FirstName.trim();
        String lastName = contact.LastName == null ? '' : contact.LastName.trim();
        String contactName = (firstName + ' ' + lastName).trim();
        String name = (contactName.length() > 0 ? contactName + ' ' : '') +
                      'Donation ' + String.valueOf(giftDate);

        Opportunity gift = new Opportunity(
            Name = name,
            AccountId = contact.AccountId,
            CloseDate = giftDate,
            StageName = 'Closed Won',
            Amount = amount,
            npsp__Primary_Contact__c = contactId
        );
        insert gift;

        // Ensure exactly one paid payment.
        List<npe01__OppPayment__c> payments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Payment_Date__c,
                   npe01__Scheduled_Date__c, npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :gift.Id
        ];

        if (payments.isEmpty()) {
            insert new npe01__OppPayment__c(
