public with sharing class TA_Opportunity_CollectForErpSync implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {
    private static final Set<Id> opportunityIdsToSync = new Set<Id>();

    public static Set<Id> getOpportunityIdsToSync() {
        return opportunityIdsToSync;
    }

    public static void clearOpportunityIdsToSync() {
        opportunityIdsToSync.clear();
    }

    public void afterInsert(List<SObject> triggerNew) {
        for (SObject sObject : triggerNew) {
            Opportunity opportunity = (Opportunity) sObject;
            opportunityIdsToSync.add(opportunity.Id);
        }
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, SObject> oldRecordsById = new Map<Id, SObject>(triggerOld);

        for (SObject sObject : triggerNew) {
            Opportunity newOpportunity = (Opportunity) sObject;
            Opportunity oldOpportunity = (Opportunity) oldRecordsById.get(newOpportunity.Id);

            if (oldOpportunity != null && newOpportunity.StageName != oldOpportunity.StageName) {
                opportunityIdsToSync.add(newOpportunity.Id);
            }
        }
    }
}
