```apex
/*
 * Trigger action to maintain Account.FB_Open_Case_Count__c
 * as the number of non-closed Cases on that Account.
 *
 * Runs in system mode intentionally: this rollup must count every Case
 * and maintain a system-owned Account field regardless of the caller's sharing.
 */
public without sharing class TA_Case_RollupOpenCount
        implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate,
        TriggerAction.AfterDelete, TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> accountIds = getAccountIds(triggerNew);
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Integer> counts = new Map<Id, Integer>();
        for (Id accountId : accountIds) {
            counts.put(accountId, 0);
        }
        counts.putAll(getOpenCaseCounts(accountIds));
        updateAccounts(counts);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        if (!hasRelevantChange(triggerNew, triggerOld)) {
            return;
        }

        Set<Id> newAccountIds = getAccountIds(triggerNew);
        Set<Id> oldAccountIds = getAccountIds(triggerOld);

        Map<Id, Integer> counts = new Map<Id, Integer>();
        for (Id accountId : newAccountIds) {
            counts.put(accountId, 0);
        }
        for (Id accountId : oldAccountIds) {
            counts.put(accountId, 0);
        }
        if (counts.isEmpty()) {
            return;
        }

        // Two queries stay within the IN-clause limit even when 200 Cases
        // are each moved from one Account to another.
        counts.putAll(getOpenCaseCounts(newAccountIds));
        counts.putAll(getOpenCaseCounts(oldAccountIds));
        updateAccounts(counts);
    }

    public void afterDelete(List<SObject> triggerOld) {
        Set<Id> accountIds = getAccountIds(triggerOld);
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Integer> counts = new Map<Id, Integer>();
        for (Id accountId : accountIds) {
            counts.put(accountId, 0);
        }
        counts.putAll(getOpenCaseCounts(accountIds));
        updateAccounts(counts);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        Set<Id> accountIds = getAccountIds(triggerNew);
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Integer> counts = new Map<Id, Integer>();
        for (Id accountId : accountIds) {
            counts.put(accountId, 0);
        }
        counts.putAll(getOpenCaseCounts(accountIds));
        updateAccounts(counts);
    }

    private Set<Id> getAccountIds(List<SObject> records) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject record : records) {
            Id accountId = (Id) record.get('AccountId');
            if (accountId != null) {
                accountIds.add(accountId);
            }
        }
        return accountIds;
    }

    private Boolean hasRelevantChange(List<SObject> triggerNew, List<SObject> triggerOld) {
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Case newCase = (Case) triggerNew[i];
            Case oldCase = (Case) triggerOld[i];
            if (newCase.AccountId != oldCase.AccountId || newCase.IsClosed != oldCase.IsClosed) {
                return true;
            }
        }
        return false;
    }

    private Map<Id, Integer> getOpenCaseCounts(Set<Id> accountIds) {
        Map<Id, Integer> counts = new Map<Id, Integer>();
        if (accountIds.isEmpty()) {
            return counts;
        }

        for (AggregateResult result : [
            SELECT AccountId, COUNT(Id) openCount
            FROM Case
            WHERE AccountId IN :accountIds
                AND IsClosed = false
            GROUP BY AccountId
        ]) {
            counts.put((Id) result.get('AccountId'), (Integer) result.get('openCount'));
        }
        return counts;
    }

    private void updateAccounts(Map<Id, Integer> counts) {
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : counts.keySet()) {
            accountsToUpdate.add(new Account(
                Id = accountId,
                FB_Open_Case_Count__c = counts.get(accountId)
            ));
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
