public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    private static Set<Id> loggedOpportunityIds = new Set<Id>();

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Opportunity> oldOpps = new Map<Id, Opportunity>();
        for (SObject oldRec : triggerOld) {
            oldOpps.put(oldRec.Id, (Opportunity) oldRec);
        }

        List<Task> tasks = new List<Task>();
        for (SObject newRec : triggerNew) {
            Opportunity opp = (Opportunity) newRec;
            Opportunity oldOpp = oldOpps.get(opp.Id);
            if (oldOpp == null) {
                continue;
            }
            if (opp.Amount == oldOpp.Amount) {
                continue;
            }
            if (loggedOpportunityIds.contains(opp.Id)) {
                continue;
            }
            tasks.add(new Task(
                Subject = 'Amount changed',
                WhatId = opp.Id,
                Status = 'Completed'
            ));
            loggedOpportunityIds.add(opp.Id);
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
}
